patches.repl:
let rate = r.casualty_percentage != null ? r.casualty_percentage
  : (r.strength && r.casualties != null ? Math.round(r.casualties / r.strength * 1000) / 10 : null);
// losses cannot exceed the men engaged: a rate above 100 % means the two numbers of the record are not for the same body of men, and it is not printed (the key action below says why)
const rateOver = rate != null && rate > 100;
if (rateOver) rate = null;
document.getElementById('b-rate').textContent = rate != null ? rate + '%' : '—';
document.getElementById('b-rate').title = rateOver ? "No rate is given: the losses and the strength in this record are not for the same body of men (see the key action)." : '';

